function moonPhase(date){
  const synodic=29.530588853;
  const ref=Date.UTC(2000,0,6,18,14,0)/86400000;        // known new moon
  const now=date.getTime()/86400000;
  const phase=(((now-ref)%synodic)+synodic)%synodic/synodic;   // 0 new .. .5 full .. 1 new
  const frac=(1-Math.cos(2*Math.PI*phase))/2;            // illuminated fraction
  return {phase, frac, waxing:phase<0.5};
}

renderMoonBodyBeforeDom:
let frac, waxing;
const date=simDate();                                            // moon phase advances with simTime (debug fast-forward spans days)
if(SIM.moon!=null){                                              // sim: forced phase for testing
  frac=clamp(+SIM.moon); waxing=SIM.wax!=="0";
} else if(isFinite(+lat) && isFinite(+lon)){                     // real: accurate illuminated fraction + waxing/waning sense
  const il=moonIllum(date); frac=il.fraction; waxing=il.waxing;
} else {                                                         // no coords yet: a plausible moon, never NaN
  const mp=moonNow(); frac=mp.frac; waxing=mp.waxing;
}
// ONE steady UPRIGHT face: renderMoonPBR lights the bright limb on the RIGHT (waxing) / LEFT (waning) with the
// maria FIXED, so the terminator just sweeps across — the disc never rotates ("record-player" spin) and its lit
// side matches the footer phase emoji. (Previously the χ−q parallactic orientation rotated the whole disc over
// time, which read as the moon spinning and mismatching the emoji.)
// CINEMATIC POSITION: real altitude + hour angle drive a rising/setting path (never pinned). H maps to
// x (east/rising→left, transit→centre, west/setting→right); altitude maps to y (arcs up when high; sits
// low at/just below the horizon when down). Below the horizon it degrades to a low, small calendar marker.
let alt=25, Hm=0;
if(SIM.moonAlt!=null){ alt=+SIM.moonAlt; Hm=SIM.moonH!=null?+SIM.moonH:0; }
else if(isFinite(+lat) && isFinite(+lon)){ const aa=moonAltAz(date, Math.max(-89.5,Math.min(89.5,+lat)), +lon); alt=aa.alt; Hm=aa.H; }
const up=clamp((alt+2)/6);                                       // 0 below horizon → 1 a few degrees up
// RESERVED top-right lunar slot — a LARGE, corner-clipped moon (≈1.9× the old size) that ENTERS and EXITS
// by a positional SWEEP, not a fade: as it rises (up:0→1) it slides in from off the upper-right corner —
// LEFT + DOWN with a slight zoom — and settles into its slot; as it sets (up:1→0) it reverses (right-out +
// up + shrink) and clips back off the corner. Opacity only ASSISTS at the extremes (see --moonfeat). It
// stays high in the corner (a clear gap above the always-low/descending arc at this x) and never sweeps
// across the centre/header. A faint culmination lift keeps a high moon from looking frozen.
const sweep=up, hd=Math.max(-1,Math.min(1,Hm/120));
// The moon SETTLES into a mostly-on-card top-right slot in EVERY visible state (a below-horizon moon only ever
// shows at night as the calendar ghost — by day moongrp→0 — so it must NOT be jammed off the corner). The sweep
// now only adds a small rise/settle for life; it no longer flings the disc off-card.
const x=268 + hd*1.5;                                            // centred so the WHOLE disc has comfortable margin on the right (≈5px) — a thin WAXING crescent's lit right limb is clearly in frame, not at the edge — while the left limb clears the temperature strap row below
const y=55 + 3*sweep - clamp((alt-6)/70)*3;                      // ≈55-58: dropped below the temp strap (y19-37) and above the arc (top y≈121 on the right) — its wide middle clears the strap, so the disc is large AND fully on-card
const scale=MOON_SCALE_MIN + (MOON_SCALE_MAX-MOON_SCALE_MIN)*sweep;                                  // large readable disc (~+11-13% vs the old corner moon) sized to FIT the pocket with right-edge margin; whole disc + phase visible, clear of temp / arc / focal text
const transform=`translate(${x.toFixed(1)} ${y.toFixed(1)}) scale(${scale.toFixed(3)})`;

lunarPresentation:
function lunarPresentation(solarElevation){
  const mFrac=clamp(moonSky.frac),moonUp=clamp((moonSky.alt+2)/6);
  const darkness=clamp(-(solarElevation+3)/9),phaseVis=clamp((mFrac-0.02)/0.05);
  const moonObject=_pbrFailed?0:moonUp*darkness*phaseVis;
  const moonLightEligible=moonObject>0;
  const moonLightReason=_pbrFailed?"surface-unavailable":darkness===0?"daylight":moonUp===0?"below-horizon":phaseVis===0?"near-new":"eligible";
  const moonLocalWash=moonLightEligible?clamp(mFrac*moonUp*1.15):0;
  const moonGlow=moonLightEligible?(0.03+0.24*mFrac*mFrac):0;
  const moonlight=moonObject*(0.35+0.65*mFrac),moonShow=clamp(darkness*1.8);
  return {mFrac,moonUp,darkness,phaseVis,moonObject,moonLightEligible,moonLightReason,moonLocalWash,moonGlow,moonlight,moonStrength:moonlight,moonShow,moonPresence:moonShow};
}

